  3	public class RabinKarp {
  4	
  5	    private static final int RADIX = 256;
  6	    private static final int MODULUS = 101;
  7	
  8	    static ArrayList<Integer> search(String pattern, String text) {
  9	        if (pattern == null || text == null) {
 10	            throw new IllegalArgumentException("Pattern and text must be non-null.");
 11	        }
 12	
 13	        int patternLength = pattern.length();
 14	        int textLength = text.length();
 15	        ArrayList<Integer> matches = new ArrayList<>();
 16	
 17	        if (patternLength == 0) {
 18	            for (int i = 0; i <= textLength; i++) {
 19	                matches.add(i);
 20	            }
 21	            return matches;
 22	        }
 23	
 24	        if (textLength < patternLength) {
 25	            return matches;
 26	        }
 27	
 28	        int highOrderMultiplier = computeHighOrderMultiplier(patternLength);
 29	        int patternHash = computeHash(pattern, patternLength);
 30	        int windowHash = computeHash(text, patternLength);
 31	
 32	        for (int start = 0; start <= textLength - patternLength; start++) {
 33	            if (patternHash == windowHash && matchesAt(text, pattern, start)) {
 34	                matches.add(start);
 35	            }
 36	
 37	            if (start < textLength - patternLength) {
 38	                windowHash = rollHash(
 39	                    windowHash,
 40	                    text.charAt(start),
 41	                    text.charAt(start + patternLength),
 42	                    highOrderMultiplier
 43	                );
 44	            }
 45	        }
 46	
 47	        return matches;
 48	    }
 49	
 50	    private static int computeHighOrderMultiplier(int patternLength) {
 51	        int highOrderMultiplier = 1;
 52	        for (int i = 0; i < patternLength - 1; i++) {
 53	            highOrderMultiplier = (highOrderMultiplier * RADIX) % MODULUS;
 54	        }
 55	        return highOrderMultiplier;
 56	    }
 57	
 58	    private static int computeHash(String value, int length) {
 59	        int hash = 0;
 60	        for (int i = 0; i < length; i++) {
 61	            hash = (RADIX * hash + value.charAt(i)) % MODULUS;
 62	        }
 63	        return hash;
 64	    }
 65	
 66	    private static boolean matchesAt(String text, String pattern, int startIndex) {
 67	        for (int i = 0; i < pattern.length(); i++) {
 68	            if (text.charAt(startIndex + i) != pattern.charAt(i)) {
 69	                return false;
 70	            }
 71	        }
 72	        return true;
 73	    }
 74	
 75	    private static int rollHash(
 76	        int currentHash,
 77	        char outgoingChar,
 78	        char incomingChar,
 79	        int highOrderMultiplier
 80	    ) {
 81	        int nextHash = (
 82	            RADIX * (currentHash - outgoingChar * highOrderMultiplier) + incomingChar
 83	        ) % MODULUS;
 84	
 85	        if (nextHash < 0) {
 86	            nextHash += MODULUS;
 87	        }
 88	
 89	        return nextHash;
 90	    }
